module.exports = JSON.parse('{"name":"Adharsh","headerTaglineOne":"Hello ","headerTaglineTwo":"I\'m Adharsh Anand","headerTaglineThree":"Code. Create. Innovate.","headerTaglineFour":"","showCursor":false,"showBlog":false,"darkMode":true,"showResume":true,"socials":[{"id":"1","title":"Github","link":"https://github.com/adharsh2608"},{"id":"2","title":"LinkedIn","link":"https://www.linkedin.com/in/adharsh-anand-b32728288/"},{"id":"3","title":"Twitter","link":"https://x.com/Adharsh2608"},{"id":"4","title":"Leetcode","link":"https://leetcode.com/u/Adharsh2608/"},{"id":"5","title":"Email","link":"mailto:adharshrtc@gmail.com"}],"projects":[{"id":"1","title":"OCTOPUS","description":"Responsive web application simulating real time conversations using Gemini clone API. Developed a chat interface using React, simulating real-time conversations with the Gemini Clone API. Implemented API calls for dynamic data responses and enhanced user interaction. Managed state efficiently with React Hooks.","imageSrc":"images/Octopus.png","url":"https://github.com/adharsh2608/Octopus"},{"id":"2","title":"Classification of Fashion Products using CNN","description":"Implemented and optimized CNN architectures (ResNet, VGG, MobileNet) for image classification using PyTorch, trained across multiple datasets with varying class sizes, image counts, and complexities.","imageSrc":"images/fashion.jpeg","url":"https://github.com/adharsh2608/Fashion_Classification"},{"id":"3","title":"Warzone Game","description":"Developed and implemented advanced decision-making algorithms for various game modes, honing key skills in predictive modeling and problem-solving. Created and executed detailed JUnit test cases to ensure robust and reliable software performance.  Applied design patterns such as MVC, State, Strategy, and Adapter, demonstrating the ability to use architectural solutions for complex challenges.","imageSrc":"images/warzone.png","url":"https://github.com/adharsh2608/WarZone-Game"},{"id":"4","title":"Sign Language Interpreter Using Deep Learning","description":"Designed and implemented a cross-platform application using LSTM to convert American Sign Language (ASL) gestures into real-time text and speech output. Built an RNN model with data preprocessing, keypoint extraction, and neural network training, enhancing communication for the hearing impaired.","imageSrc":"images/sign language.jpeg","url":"https://github.com/adharsh2608/Sign-Language-Interpretation"}],"aboutpara":"I am a passionate and driven Master’s student in Applied Computer Science at Concordia University, with a strong foundation in software development, artificial intelligence, and data management. My academic journey, coupled with hands-on experience as a Software Developer Intern, has equipped me with a diverse skill set in programming languages such as Java, Python, C++, and Dart, as well as expertise in frameworks like Flutter, TensorFlow, and Angular. I thrive on solving complex problems and have a proven track record of developing innovative solutions, from cross-platform mobile applications to AI-driven web interfaces. My projects, including a Sign Language Interpreter using Deep Learning and an RFID-Enabled Automated Billing System, reflect my ability to leverage cutting-edge technologies to create impactful solutions. I am eager to contribute my technical skills and creativity to challenging projects while continuing to grow as a professional in the tech industry.","resume":{"tagline":"Master\'s in Applied Computer Science | Python Enthusiast | Loves to build complex software | Web Development | App Development | Artificial Intelligence","description":"With a strong foundation in computer science and hands-on experience in software development, I specialize in creating cross-platform applications, optimizing system performance, and leveraging cutting-edge technologies like AI and IoT. My expertise spans mobile and web development, data analysis, and machine learning, with a focus on delivering user-centric solutions.","experiences":[{"id":"vosyn-2025","dates":"June 2025 - Present","type":"Vosyn Inc., Toronto, Canada","position":"Front End Developer Intern","bullets":"Developed the core front end of a dynamic content discovery platform featuring movies, audiobooks, podcasts, articles, and journals building interactive dashboards, media cards, and tab-based navigation using React.js, Next.js, (MUI), and Tailwind CSS. Translated high-fidelity UI/UX designs into responsive components with custom interactions like shuffle functionality, playback timers, and social media widgets ensuring cross-device consistency and accessibility compliance across all content modules."},{"id":"1","dates":"April 2023 - February 2024","type":"Kaardeep Engineering","position":"Full-Stack Developer Intern","bullets":"Developed and designed a mobile application with a primary focus on automating messaging. This involved utilizing the Flutter framework and Dart as the programming language. Engineered the user interface of the mobile application, enabling the company to promptly notify customers about service updates using Firebase."},{"id":"d495c23b-4f65-479a-9b8a-cfbc1c089725","dates":"July 2022 - August 2022 ","type":"ResQ Technologies Private Limited","position":"Software Developer Intern","bullets":"Developed a cross-platform mobile application using Flutter framework to accomplish a sophisticated smart monitoring system for boats which offers seamless functionality across multiple platforms while maintaining a unified codebase for streamlined device management. Designed and executed a robust GPS tracking and Geo-fencing system that enhanced security measures resulting in a substantial 26 percent reduction in likelihood of theft. Optimized API configurations and managed a complex bug fix for the MQTT module, resulting in a notable 17 percent reduction in sensor data retrieval time thereby contributing to 23 percent improvement in the overall program’s execution time."},{"id":"d4414002-1845-4a28-ae7e-e4597279a5b7","dates":"December 2021 - June 2022","type":"AnDnR Soft Solutions Private Limited","position":"Software Developer Intern","bullets":"Engineered end-to-end solutions using Node.js, React.js, Oracle, Google API and Zoho API, achieving a 25% improvement in overall system efficiency and reduced API response times. Collaborated with cross-functional teams (UI/UX, QA, DevOps) to design and develop new features, leveraging Figma for rapid prototyping and ensuring seamless data exchange across platforms. Implemented best coding practices (automated testing, code reviews, and Agile ceremonies) to maintain high code quality and foster a culture of continuous improvement."}],"education":{"universityName":"Concordia University","universityDate":"2023-2025","universityPara":"Master of Engineering in Applied Computer Science"},"languages":["Javascript","HTML5","CSS","Python","Java"],"frameworks":["React","NodeJs","Tensorflow","Flutter","Angular"],"others":["Figma","AdobeXD","AWS","Github","Firebase"]}}');

